def apply(output,text):
    rows=RECIPES.get(output)
    if rows is None:return text
    # Fully adapted output is idempotent even where later source hunks include
    # earlier fragments. Compare the whole final recipe, not a prefix match.
    candidate=text
    for row in rows:
        before,after,count=row['before'],row['after'],row['count']
        if candidate.count(after)==count:
            continue
        actual=candidate.count(before)
        if actual!=count:
            raise ValueError('Original v025 comment layout mismatch: '+output+' '+str(actual)+' != '+str(count))
        candidate=candidate.replace(before,after,count)
    return candidate
